void W906_TesterCommInit()
{
    //AI(W906-D1D7) 20260928 (St02-E): golden TfMain::ChangeTesterConnect D1/D2/D3/D6/D7 (HandlerTesterConnect.cpp) -- Handler
    //   rules, not the bridge, so they are installed before the HT9045_TESTERCOMM=0 opt-out below.  Idempotent.
    W906_TesterConnectRulesInstall();
    if (g_inited)
        return;
    //AI(W906-GB-P3) 20260926: default = golden -- from here on ProcessHVisionConnect (Tick, every 1000 ms) launches the
    //   bridge like golden launches H9046_32GPIB.exe / RS232Standard.exe at boot: the engine thread starts, writes its
    //   golden logs, opens its GPIB card / COM ports.  HT9045_TESTERCOMM=0 opts a run out entirely (seat not installed,
    //   no engine, Tick/Poll/Shutdown inert, the page shows offline) -- for SIM regression runs that must not see a bridge.
    W906_CmdServersEnsure();  const char* optOut = std::getenv("HT9045_TESTERCOMM");   // AI(W906-W10fix) 20260928 (St02-E): fMain's 7016 / 7017 objects exist even with the opt-out (WebStart.cpp:3483-3486 writes their Active on every Start)
    if (optOut && optOut[0] == '0' && optOut[1] == '\0')
        return;
    g_inited = true;
    testercomm::TesterCommHub& hub = testercomm::TesterCommHub::Instance();
    // golden WakeupGPIB (main.cpp:18545-18553): RS232_MODE, or TTL_MODE with TTL_CARD_TYPE 2/3, launches
    // RS232Standard.exe; every other type launches H9046_32GPIB.exe (TCP_IP_MODE included -- golden runs the GPIB
    // bridge alongside the Handler's built-in TCP channel).  TTL_MODE with TTL_CARD_TYPE<2 (the direct DIO-card
    // branch) is not used on the new machines (user ruling 20260926), so TTL_MODE always gets RS232Standard here.
    hub.RegisterFactory(testercomm::kTestTypeGpib,  &gpibbridge::GpibEngine::Create);
    hub.RegisterFactory(testercomm::kTestTypeTcpIp, &gpibbridge::GpibEngine::Create);
    hub.RegisterFactory(testercomm::kTestTypeRs232, &rs232std::Rs232Engine::Create);
    hub.RegisterFactory(testercomm::kTestTypeTtl,   &rs232std::Rs232Engine::Create);
    if (fTesterSide == NULL)
        fTesterSide = new THandlerTesterSide();
    fTesterSide->Attach(&hub);  ht9045::W906_ESDErrorDrainHook = &THandlerTesterSide::ESDErrorDrainHook;  ht9045::W906_ESCProcessHook = &THandlerTesterSide::ProcessForESCHook;   /* AI(W906-ST02-ESC) 20261005 (St02-E): golden Timer1 :2858 ProcessForESC seat */   //AI(W906-S13) 20261001 (St02-E): the tESDError part of golden TimerESDTimer (MainTimerESD.cpp E2), installed on every TesterComm init right after fTesterSide exists (not on :119, the if body -- -Wmisleading-indentation); the hook checks fTesterSide itself (Shutdown sets it NULL)
    W906_TesterForward.SendMSG_CMD              = &FwdSendCmd;          //AI(W906-GB-P2b) 20260926: install seat
    W906_TesterForward.SendMSG_CMD_Msg          = &FwdSendCmdMsg;
    W906_TesterForward.RunTestProgram           = &FwdRunTestProgram;
    W906_TesterForward.CloseGpibProgram         = &FwdCloseGpibProgram;
    W906_TesterForward.SendMSG_TestMode         = &FwdSendTestMode;
    W906_TesterForward.WakeupGPIB               = &FwdWakeupGPIB;
    W906_TesterForward.SendMSG_CMD_DeviceMapSRQ = &FwdDeviceMapSRQ;
    W906_TesterForward.BridgeFound              = &FwdBridgeFound;
    W906_TesterHandlerWndHook                   = &FwdHandlerWnd;       //AI(W906-GB-P8) 20260928 (St02-E helper): B1 seats (TesterComm/TesterWndSeat.h)
    W906_TesterBridgeWndHook                    = &FwdBridgeWnd;
    W906_TesterSendToBridgeHook                 = &FwdSendToBridge;
    g_lastConnect = ::GetTickCount() - kConnectPeriodMs;   // first ProcessHVisionConnect on the first tick
    W906_GpibAuxEnable(true);   //AI(W906-GB-P6) 20260926: 2A + Q2(a) -- only the composition root (wb_serve) reads / seeds the recipe
    W906_TcpPumpInit(W906_TcpTesterRealSocket());  { const char* w10Sim = std::getenv("HT9045_TCPCMD_SIM"); W906_CmdServerPumpInit(W906_SimTcpRealSockets(!(w10Sim && w10Sim[0] == '1' && w10Sim[1] == '\0'))); }  W906_HanaRmsSetRealSocket(W906_TcpTesterRealSocket());   /* AI(W906-ST02-C10) 20261002 (St02-E helper): golden 912 HANARMSClient (ctNonBlocking) follows the TCP tester socket policy -- SIM build Sim, SHIP real unless HT9045_TCPCMD_SIM=1 */   // P5: the Handler's built-in TCP/IP tester channel (golden TfTesterTCP).  AI(W906-W10) 20260927 (St02-E): golden TCPCommandServer / TeraTCPResultServer as polled real sockets (HT9045_TCPCMD_SIM=1 keeps them Sim).  AI(W906-W10fix) 20260928: that block sat behind the P5 comment (dead)   //AI(W906-W58-4) 20260930 (St02-E): W58-4 -- SIM build: real 7016 / 7017 sockets only with W906_SIM_TCP_SERVERS=1 (end of file)
}

static void TestDriverWrappers()
{
    using namespace gpibbridge;
    SetGpibDriver(0);
    CHECK(ibfind("GPIB0") < 0);
    CHECK((ibsta & ERR) != 0);
    char b[8];
    ibrd(0, b, sizeof(b));
    CHECK((ibsta & ERR) != 0);

    SimGpibDriver sim;
    SetGpibDriver(&sim);
    CHECK(ibfind("GPIB0") == 0);
    CHECK((ibsta & ERR) == 0);
    ibpad(0, 5);
    CHECK(sim.PrimaryAddress() == 5);

    ibwait(0, 0);
    CHECK((ibsta & LACS) == 0);
    sim.TesterWrite("FULLSITES?");
    ibwait(0, 0);
    CHECK((ibsta & LACS) != 0);
    char buf[64];
    std::memset(buf, 0, sizeof(buf));
    ibrd(0, buf, sizeof(buf) - 1);
    CHECK(ibcnt == 10);
    CHECK(std::strcmp(buf, "FULLSITES?") == 0);
    CHECK((ibsta & END) != 0);
    ibwait(0, 0);
    CHECK((ibsta & LACS) == 0);

    // not addressed to talk: the write fails like a real device write with no listener
    const char* ans = "Fullsites 00000003";
    ibwrt(0, ans, (long)std::strlen(ans));
    CHECK((ibsta & ERR) != 0);
    CHECK(sim.TakeBridgeWrites().empty());
    sim.SetTalkAddressed(true);
    ibwait(0, 0);
    CHECK((ibsta & TACS) != 0);
    ibwrt(0, ans, (long)std::strlen(ans));
    CHECK((ibsta & ERR) == 0);
    CHECK(ibcnt == (long)std::strlen(ans));
    std::vector<std::string> w = sim.TakeBridgeWrites();
    CHECK(w.size() == 1 && w[0] == ans);

    ibrsv(0, 0x41);
    std::vector<int> srq = sim.TakeSrqBytes();
    CHECK(srq.size() == 1 && srq[0] == 0x41);

    sim.FindFails = true;
    CHECK(ibfind("GPIB0") < 0);
    CHECK((ibsta & ERR) != 0);
    SetGpibDriver(0);
}

static void OneLife(testercomm::TesterCommHub& hub, Recorder& r, int life)
{
    const size_t base = r.packets.size();
    CHECK(hub.SelectTestType(testercomm::kTestTypeGpib));

    // Timer1 (300 ms) -> ProcessHMountConnect once a second -> SleepEx(1000) -> Version, TesterMode
    const bool gotVersion = PumpUntil(hub, r, MSG_CMD_Version, base, 8000);
    CHECK(gotVersion);
    if (!gotVersion)
        std::printf("  life %d: no MSG_CMD_Version (packets %u)\n", life, (unsigned)(r.packets.size() - base));
    const int iv = FindCommand(r, MSG_CMD_Version, base);
    if (iv >= 0)
    {
        webbridge::WbGuard g(r.mu);
        const VM& v = r.packets[(size_t)iv];
        CHECK(std::strcmp(v.cReturn, "V12.13.905.0") == 0);   // golden: GPIBVersion=VerInfo().GetFileVersion()
        if (std::strcmp(v.cReturn, "V12.13.905.0") != 0)
            std::printf("  life %d: version '%s'\n", life, v.cReturn);
    }
    CHECK(PumpUntil(hub, r, MSG_CMD_TesterMode, base, 2000));
    CHECK(hub.IsUp());
    std::string simUi; unsigned long simSeq=0;
    CHECK(testercomm::UiChannel::Instance().Read("gpib", &simUi, &simSeq));
    int expectedBin=1;
#ifdef SOFT_SIMULTE
    if(const char* seed=std::getenv("W906_SIM_TEST_BIN")) {
        char* end=nullptr; const long bin=std::strtol(seed, &end, 10);
        if(end!=seed && *end=='\0' && bin>=1 && bin<=14) expectedBin=static_cast<int>(bin);
    }
#endif
    char binNeedle[40]; std::sprintf(binNeedle, ",\"bin\":%d,", expectedBin);
    CHECK(simUi.find(binNeedle)!=std::string::npos);
    CHECK(gpibbridge::GpibEngine::BridgeWndToken() != 0);
    CHECK(gpibbridge::GpibEngine::HandlerWndToken() != 0);

    // Handler -> bridge: CloseGpib (golden CloseGpibProgram)
    MV mv;
    std::memset(&mv, 0, sizeof(mv));
    mv.iSendCommand = MSG_CMD_CloseGpib;
    mv.bCloseGpib = true;
    mv.HandlerHwnd = gpibbridge::GpibEngine::HandlerWndToken();
    mv.GpibHwnd = gpibbridge::GpibEngine::BridgeWndToken();
    int result = -1;
    CHECK(hub.SendToEngine(std::string(reinterpret_cast<const char*>(&mv), sizeof(mv)), &result) == testercomm::kSent);
    const DWORD t0 = ::GetTickCount();
    while (hub.IsUp() && ::GetTickCount() - t0 < 2000)
    {
        hub.PollHandler();
        ::Sleep(5);
    }
    CHECK(!hub.IsUp());

    hub.Shutdown();
    CHECK(gpibbridge::GpibEngine::BridgeWndToken() == 0);
}

static void TestFullLifecycle()
{
    const char* on = std::getenv("HT9045_GPIB_FULL_TEST");
    if (!on || std::strcmp(on, "1") != 0)
    {
        std::printf("full lifecycle: skipped (set HT9045_GPIB_FULL_TEST=1; writes D:\\GPIBLOG like golden)\n");
        return;
    }
    char tmp[MAX_PATH];
    ::GetTempPathA(sizeof(tmp), tmp);
    std::string dir = std::string(tmp) + W906_TestTmpName("ht9045_gpib_ctest");   // AI(W906-ST02-C17) 20261005 (St02-E): per-process scratch name (St01 E-039; tests/w906_test_tmpname.h)
    ::CreateDirectoryA(dir.c_str(), 0);
    const std::string gen = dir + "\\general.ini";
    const std::string hgen = dir + "\\Gerneral.ini";
    WriteText(gen, "[Version]\r\nModel=9045GPIB\r\n");
    // CUSTOMER_CODE 910 (CC_SPIL_SHINCHU) is not in golden RS232.cpp:112-119, so the aux RS232 line defaults to OFF
    // and no real COM port is opened (code 0 = CC_HONPREC_QC would default it ON and open Setup.ini's COM port).
    WriteText(hgen, "[Version]\r\nModel=HT-9045\r\n[System]\r\nCUSTOMER_CODE=910\r\n");
    gpibbridge::GpibEngine::OverrideIniPaths(gen, hgen);   // applied after the per-life ResetBridgeGlobals()

    gpibbridge::SimGpibDriver sim;
    gpibbridge::GpibEngine::InjectDriver(&sim);

    Recorder r;
    r.threadId = ::GetCurrentThreadId();
    testercomm::TesterCommHub hub;
    hub.RegisterFactory(testercomm::kTestTypeGpib, &gpibbridge::GpibEngine::Create);
    hub.SetHandlerSink(&RecordSink, &r);

    OneLife(hub, r, 1);
    OneLife(hub, r, 2);
    CHECK(!r.wrongThread);   // every bridge -> Handler packet was served on this (Handler) thread
    CHECK(hub.Thread().EngineErrors() == 0);
    CHECK(hub.HandlerErrors() == 0);         // exceptions out of OnMyCopyMsg
    if (hub.Thread().EngineErrors() != 0)
        std::printf("  TesterComm thread errors: %lu\n", hub.Thread().EngineErrors());

    gpibbridge::GpibEngine::InjectDriver(0);
    gpibbridge::GpibEngine::OverrideIniPaths(std::string(), std::string());
    W906_TestTmpRemoveTree(dir);   // AI(W906-ST02-C17) 20261005 (St02-E): per-process scratch name (St01 E-039; tests/w906_test_tmpname.h): remove this run's scratch folder
}

int main()
{
    TestLink();
    TestDriverWrappers();
