    TestFullLifecycle();
    std::printf("test_testercomm_gpib: %d/%d passed\n", g_total - g_fail, g_total);
    return g_fail == 0 ? 0 : 1;
}

static void TestEndToEnd()
{
    const char* on = std::getenv("HT9045_TESTERCOMM_E2E");
    if (!on || std::strcmp(on, "1") != 0)
    {
        std::printf("end-to-end: skipped (set HT9045_TESTERCOMM_E2E=1; the GPIB engine writes D:\\GPIBLOG like golden)\n");
        return;
    }
    char tmp[MAX_PATH];
    ::GetTempPathA(sizeof(tmp), tmp);
    const std::string dir = std::string(tmp) + W906_TestTmpName("ht9045_handler_ctest");   // AI(W906-ST02-C17) 20261005 (St02-E): per-process scratch name (St01 E-039; tests/w906_test_tmpname.h)
    ::CreateDirectoryA(dir.c_str(), 0);
    const std::string gen = dir + "\\general.ini", hgen = dir + "\\Gerneral.ini";
    FILE* f = std::fopen(gen.c_str(), "wb");
    if (f) { std::fputs("[Version]\r\nModel=9045GPIB\r\n", f); std::fclose(f); }
    f = std::fopen(hgen.c_str(), "wb");
    if (f) { std::fputs("[Version]\r\nModel=HT-9045\r\n[System]\r\nCUSTOMER_CODE=910\r\n", f); std::fclose(f); }
    gpibbridge::GpibEngine::OverrideIniPaths(gen, hgen);
    gpibbridge::SimGpibDriver sim;
    gpibbridge::GpibEngine::InjectDriver(&sim);

    TfMain* oldMain = fMain;
    TesterFMain* testerMain = new TesterFMain();
    fMain = testerMain;

    testercomm::TesterCommHub hub;
    hub.RegisterFactory(testercomm::kTestTypeGpib, &gpibbridge::GpibEngine::Create);
    THandlerTesterSide side;
    fTesterSide = &side;
    side.Attach(&hub);
    InitialOK = true;
    bSystemClose = false;
    TestIF.iTestType = GPIB_MODE;
    TestIF_File.iTestType = GPIB_MODE;
    MachineTypeChoice = Type_HT9045;

    CHECK(side.StartBridgeProgram());
    // Timer1 -> ProcessHMountConnect (once a second, SleepEx(1000)) -> Version + TesterMode to this side
    const DWORD t0 = ::GetTickCount();
    unsigned long lastSink = side.sinkMessages;
    while (::GetTickCount() - t0 < 10000 && side.sinkMessages < lastSink + 2)
    {
        hub.PollHandler();
        ::Sleep(5);
    }
    CHECK(side.sinkMessages >= lastSink + 2);
    CHECK(hub.IsUp());

    // golden timer path: ProcessHVisionConnect finds the bridge window
    side.WakeupGPIBdelay.SetSecAndOn(0);
    side.ProcessHVisionConnect();
    CHECK(side.bFind);
    CHECK(side.HVisionWnd == gpibbridge::GpibEngine::BridgeWndToken());
    // AI(W906-ST02-C11) 20261002 (St02-E): the 9050 arm (Frank 910 main.cpp:17902-17903, RULINGS_20261002 #34 item 4) --
    //   MachineTypeChoice=Type_HT9050 must reach FindBridgeWindow() too.  WakeupGPIBdelay is armed long first, so a missing
    //   arm (HVisionWnd stays NULL, bFind=false) cannot wake a second bridge; it only fails the CHECK.
    {
        const int sType = MachineTypeChoice;
        side.WakeupGPIBdelay.SetSecAndOn(60);
        MachineTypeChoice = Type_HT9050;
        side.HVisionWnd = NULL;
        side.ProcessHVisionConnect();
        CHECK(side.bFind && side.HVisionWnd == gpibbridge::GpibEngine::BridgeWndToken());
        MachineTypeChoice = sType;
        side.WakeupGPIBdelay.SetSecAndOn(0);
        side.ProcessHVisionConnect();
        CHECK(side.bFind && side.HVisionWnd == gpibbridge::GpibEngine::BridgeWndToken());
    }

    // Handler -> bridge with the identity the bridge checks (golden OnMyCopyMsg HandlerHwnd / GpibHwnd)
    const unsigned long bridgeMsgs = gpibbridge::GpibEngine::HandlerMessages();
    side.SendMSG_TestMode();
    CHECK(gpibbridge::GpibEngine::HandlerMessages() > bridgeMsgs);
    const DWORD t1 = ::GetTickCount();
    while (::GetTickCount() - t1 < 1500)
    {
        hub.PollHandler();
        ::Sleep(5);
    }
    CHECK(hub.IsUp());   // a wrong HandlerHwnd / GpibHwnd would have made the bridge close itself

    side.CloseGpibProgram("ctest");
    CHECK(!side.bFind);
    const DWORD t2 = ::GetTickCount();
    while (hub.IsUp() && ::GetTickCount() - t2 < 2000)
    {
        hub.PollHandler();
        ::Sleep(5);
    }
    CHECK(!hub.IsUp());
    CHECK(hub.HandlerErrors() == 0);
    CHECK(hub.Thread().EngineErrors() == 0);

    hub.Shutdown();
    fTesterSide = NULL;
    fMain = oldMain;
    delete testerMain;   // through its own type: TfMain's destructor need not be virtual
    gpibbridge::GpibEngine::InjectDriver(0);
    gpibbridge::GpibEngine::OverrideIniPaths(std::string(), std::string());
    W906_TestTmpRemoveTree(dir);   // AI(W906-ST02-C17) 20261005 (St02-E): per-process scratch name (St01 E-039; tests/w906_test_tmpname.h): remove this run's scratch folder
}

int main()
{
    std::setvbuf(stdout, NULL, _IONBF, 0);   // AI(W906-TEST-SAFE) 20260928 (St02-E helper): unbuffered -- a crash report shows the exact last line
    std::printf("TesterComm_Handler\n");
    // AI(W906-TEST-SAFE) 20260928 (St02-E helper): containment first -- run by hand (no ctest environment),
    //   the 7016 pump (TCPIPCommunicationLog) and golden RecordProcess would write the machine's real D:\HT9045_Log / D:\RMS trees.
    //   Refuse, exit 2, before any Handler code (st02_test_containment.h).
    if (!W906TestInsideCtestRoots("TesterComm_Handler"))
        return 2;

    TestOffline();
    TestForwardSeat();
    TestMachineStatusSend();   // AI(W906-GB-P8) 20260928 (St02-E helper): U12
    TestEsdWindow();
    TestEsdIonBarPowerOn();
    TestEndToEnd();
    TestRemoteCmdNotIn906();   // AI(W906-ST02-C912) 20261003 (St02-E helper): back to golden 906_0625 main.cpp:15847-15858 (RULINGS_20261002 #20 / #23-6)
    std::printf("test_testercomm_handler: %d/%d passed\n", g_total - g_fail, g_total);
    return g_fail == 0 ? 0 : 1;
}

int main()
{
    g_mainThread = ::GetCurrentThreadId();
    TesterCommHub hub;
    g_hub = &hub;
    hub.RegisterFactory(kTestTypeGpib, &MakeGpib);
    hub.RegisterFactory(kTestTypeRs232, &MakeRs232);
    hub.SetHandlerSink(&HandlerSink, 0);

    // 1) start
    int r = 0;
    CHECK(hub.SendToEngine("echo:x", &r) == kNoReceiver);   // nothing selected yet
    CHECK(hub.SelectTestType(kTestTypeGpib));
    CHECK(WaitFor([&] { return hub.IsUp(); }, 2000, false));
    CHECK(std::string(hub.EngineName()) == "test-gpib");

    // 2) synchronous send
    CHECK(hub.SendToEngine("echo:abc", &r) == kSent && r == 3);

    // 3) nesting, golden SendMessage order
    TakeLog();
    CHECK(hub.SendToEngine("nest", &r, 3000) == kSent && r == 7);
    {
        std::vector<std::string> v = TakeLog();
        const char* want[] = { "E:nest", "H:back", "E:inner", "H:inner=42", "E:back=99" };
        bool ok = v.size() == 5;
        for (std::size_t i = 0; ok && i < 5; ++i)
            ok = (v[i] == want[i]);
        CHECK(ok);
        if (!ok)
            for (std::size_t i = 0; i < v.size(); ++i)
                std::printf("  log[%u] = %s\n", (unsigned)i, v[i].c_str());
    }

    // 4) timeout + late completion freed
    DWORD t0 = ::GetTickCount();
    CHECK(hub.SendToEngine("slow", &r, 50) == kTimeout);
    CHECK(::GetTickCount() - t0 < 250);   // the Handler thread was released well before the 300 ms handler ended
    CHECK(WaitFor([&] { return hub.Mailbox().Stats().abandoned == 1; }, 2000, false));
    CHECK(hub.SendToEngine("echo:xy", &r) == kSent && r == 2);

    // 5) engine -> Handler, served by PollHandler on this thread
    g_sendTick = true;
    CHECK(WaitFor([&] { return g_ticksSeen.load() > 0; }, 2000, true));
    g_sendTick = false;
    hub.PollHandler();

    // 6) exception in the engine's message handler
    CHECK(hub.SendToEngine("throw", &r) == kSent && r == -1);
    CHECK(hub.HandlerErrors() == 1);

    // 7) exception in RunOnce: counted, loop keeps running
    unsigned long hb = hub.Thread().Heartbeat();
    g_throwInRun = true;
    CHECK(WaitFor([&] { return hub.Thread().EngineErrors() >= 1; }, 2000, false));
    CHECK(WaitFor([&] { return hub.Thread().Heartbeat() > hb + 3; }, 2000, false));
    CHECK(hub.IsUp());

    // 8) isolation
    CHECK(g_threadViolations.load() == 0);

    // 9) switching
    unsigned long firstEngineThread = g_lastEngineThread.load();
    CHECK(hub.SelectTestType(kTestTypeRs232));
    CHECK(g_engineStops.load() == 1 && g_engineDeletes.load() == 1);
    CHECK(WaitFor([&] { return hub.IsUp(); }, 2000, false));
    CHECK(std::string(hub.EngineName()) == "test-rs232");
    CHECK(hub.SendToEngine("echo:abcd", &r) == kSent && r == 4);
    CHECK(g_lastEngineThread.load() != 0 && g_lastEngineThread.load() != g_mainThread);
    (void)firstEngineThread;   // not compared: Windows may reuse the old thread's id once it has exited
    CHECK(!hub.SelectTestType(kTestTypeTcpIp));   // no TCP engine registered in P0
    CHECK(g_engineStops.load() == 2 && g_engineDeletes.load() == 2);
    CHECK(hub.SendToEngine("echo:x", &r) == kNoReceiver);
    CHECK(!hub.IsUp());

    // 10) shutdown
    CHECK(hub.SelectTestType(kTestTypeGpib));
    CHECK(WaitFor([&] { return hub.IsUp(); }, 2000, false));
    hub.Shutdown();
    CHECK(!hub.Thread().Running());
    CHECK(g_engineDeletes.load() == 3);
    CHECK(g_threadViolations.load() == 0);

    std::printf("test_testercomm_ipc: %d/%d passed\n", g_total - g_fail, g_total);
    return g_fail ? 1 : 0;
}
